assign_re = re.compile(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*=\s*([^;]{0,200});?")
src_re = re.compile(r"(skb->data|skb_header_pointer\s*\(|skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\()")
def find_funcs(lines):
    funcs=[];depth=0;start=None;sig=""
    for i,l in enumerate(lines):
        if l and l[0]=="{":
            start=i;j=i-1;sig=[]
            while j>=0 and lines[j].strip()!="" and j>i-15:
                sig.insert(0,lines[j].strip());j-=1
            sig=" ".join(sig)
        depth += l.count("{")-l.count("}")
        if start is not None and depth==0:
            funcs.append((sig,start,i+1));start=None
    return funcs
out=[]
for dp,dn,fn in os.walk("."):
    for f in fn:
        if not f.endswith(".c"): continue
        p=os.path.join(dp,f)
        if not (p.startswith("./net/") or p.startswith("./drivers/")): continue
        try: lines=open(p,errors="replace").readlines()
        except: continue
        for sig,s,e in find_funcs(lines):
            body=lines[s:e]
            for i,l in enumerate(body):
                if not src_re.search(l): continue
                for m in assign_re.finditer(l):
                    var,src=m.group(1),m.group(2)
                    if not src_re.search(src): continue
                    # find next pull-ish call after this line within 25 lines
                    for j in range(i+1, min(i+26, len(body))):
                        if pull_re.search(body[j]):
                            # find use of var after pull within 30 lines
                            for k in range(j+1, min(j+31, len(body))):
                                if re.search(r"\b%s\b"%re.escape(var), body[k]):
                                    if re.search(r"\b%s\s*="%re.escape(var), body[k]) and not re.search(r"==|!=|>=|<=",body[k]): break
                                    if re.search(r"(\*%s\b|%s->|%s\[)"%((re.escape(var),)*3), body[k]):
                                        out.append({"file":p[2:],"func":sig[:70],"save":s+1+i,"pull":s+1+j,"use":s+1+k,"save_txt":body[i].strip()[:120],"pull_txt":body[j].strip()[:120],"use_txt":body[k].strip()[:120]})
                                        break
                            break
print(json.dumps(out,indent=0))
